import{_ as o,l as i,o as e,c as n,v as t,p as l,x as s,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"DNS","description":"","frontmatter":{"title":"DNS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dns.md","filePath":"cs/dns.md","lastUpdated":1789023840000}'),T={name:"cs/dns.md"};function A(D,a,h,_,P,m){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;DNS&quot;">​</a></h1><div class="epigraph"><p>域名是层次化的名字；解析器从根到权威逐级询问，得到地址或其他记录。</p><footer>—— 据 Mockapetris, RFC 1034, Domain Names — Concepts and Facilities, 1987 整理</footer></div><p><a href="/cs/quic-contrast">上一课</a>与 TCP 都假定目的是 IP。<a href="/cs/quic-contrast">DHCP</a> 交出的「DNS 服务器」还没有被使用。人不能记前缀表。缺口是 <strong>DNS</strong>：层次名字到记录（A/AAAA 等）。本课不把 HTTP 方法写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每台主机持有全球静态表，无法更新。RFC 1034：树状名字空间，每区有权威服务器；递归解析器代客户端走路：问根要 TLD，问 TLD 要权威，问权威要记录。常用 <a href="/cs/udp">UDP</a> 53，大包或区传送走 TCP。缺口不是 BGP 如何通告前缀，而是应用看见的名字。</p><p>本课不把 DNSSEC 验证链写完。</p><p><span class="marginnote">缓存按 TTL。CNAME、MX、NS 是其他记录类型。本课主干是「名字 → 地址」，为 HTTP 打开连接做准备。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用调用解析器库（后课套接字之前）。存根问本地递归；递归从根（或缓存）迭代。应答含答案或转介。与 <a href="/cs/arp">ARP</a> 对照：ARP 是一跳、广播；DNS 是应用层、全球层次、可缓存。</p>',9)),(e(),l(c,null,{default:s(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%20www.example%22%5D%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E8%A7%A3%E6%9E%90%E5%99%A8%22%5D%0A%20%20REC%20--%3E%20ROOT%5B%22%E6%A0%B9%22%5D%0A%20%20ROOT%20--%3E%20TLD%5B%22TLD%22%5D%0A%20%20TLD%20--%3E%20AUTH%5B%22%E6%9D%83%E5%A8%81%22%5D%0A%20%20AUTH%20--%3E%20A%5B%22A%2FAAAA%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DNS 让 <a href="/cs/ip-subnet">IP 编址</a> 对人隐藏，让服务可以改地址而不改名字（在 TTL 内）。端到端：解析错误会连错主机，TLS 课才用证书把名字钉到密钥；本课 DNS 本身可被污染，点名即可。Anycast 根与 CDN 的联合在再后一课。</p><p>查询走 UDP，丢失靠解析器重试，不用 TCP 可靠流，符合「短请求」的端到端选择。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DoH/DoT 的全部部署。不把 mDNS 局域网发现当全球 DNS。也不把 ENUM 电话映射写进主干。得到地址之后，应用层如何取文档，下一课 HTTP。</p><p>根与 TLD 的响应是转介不是最终答案；若把转介当 A 记录，客户端会连错。存根解析器不应自己从根走完全程，除非它就是递归器。</p><p>后课默认：主机名可解析为 IP。文档的方法、头、状态码，下一课 HTTP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DNS（RFC 1034）层次解析名字到记录，UDP 为主。</li><li>缓存 TTL；与 ARP 不在同一层。</li><li>取超文本是 HTTP 的缺口。</li><li>出处：RFC 1034；RFC 1035；Kurose and Ross。</li></ul>',9))])}const f=o(T,[["render",A]]);export{S as __pageData,f as default};
